def relabeled_clone(self, relabels):
    if not relabels:
        return self
    clone = self.clone()
    if hasattr(clone, 'alias_map'):
        clone.alias_map = {
            relabels.get(alias, alias): entry for alias, entry in clone.alias_map.items()
        }
    return clone
